import SwiftUI

/// Minimal SVG path-data parser — supports M/L/H/V/C/S/Q/T/Z (absolute + relative),
/// enough for static logo artwork exported from design tools.
enum SVGPath {
    static func cgPath(from d: String) -> CGPath {
        let path = CGMutablePath()
        let chars = Array(d.unicodeScalars)
        var i = 0
        var current = CGPoint.zero
        var subpathStart = CGPoint.zero
        var lastCubicControl: CGPoint?
        var lastQuadControl: CGPoint?
        var command: UnicodeScalar = "M"

        func isSeparator(_ c: UnicodeScalar) -> Bool {
            c == " " || c == "," || c == "\n" || c == "\r" || c == "\t"
        }

        func skipSeparators() {
            while i < chars.count, isSeparator(chars[i]) { i += 1 }
        }

        func nextNumber() -> CGFloat? {
            skipSeparators()
            var s = ""
            if i < chars.count, chars[i] == "-" || chars[i] == "+" {
                s.unicodeScalars.append(chars[i]); i += 1
            }
            var seenDot = false
            loop: while i < chars.count {
                let c = chars[i]
                switch c {
                case "0"..."9":
                    s.unicodeScalars.append(c); i += 1
                case ".":
                    if seenDot { break loop }
                    seenDot = true
                    s.unicodeScalars.append(c); i += 1
                case "e", "E":
                    s.unicodeScalars.append(c); i += 1
                    if i < chars.count, chars[i] == "-" || chars[i] == "+" {
                        s.unicodeScalars.append(chars[i]); i += 1
                    }
                default:
                    break loop
                }
            }
            guard let value = Double(s) else { return nil }
            return CGFloat(value)
        }

        func nextPoint(relative: Bool) -> CGPoint? {
            guard let x = nextNumber(), let y = nextNumber() else { return nil }
            return relative ? CGPoint(x: current.x + x, y: current.y + y) : CGPoint(x: x, y: y)
        }

        while i < chars.count {
            skipSeparators()
            guard i < chars.count else { break }
            let c = chars[i]
            if ("a"..."z").contains(c) || ("A"..."Z").contains(c) {
                command = c
                i += 1
            }
            // else: implicit repeat of previous command (M becomes L per SVG spec)

            let relative = ("a"..."z").contains(command)
            switch String(command).uppercased() {
            case "M":
                guard let p = nextPoint(relative: relative) else { return path }
                path.move(to: p)
                current = p
                subpathStart = p
                command = relative ? "l" : "L"
                lastCubicControl = nil; lastQuadControl = nil
            case "L":
                guard let p = nextPoint(relative: relative) else { return path }
                path.addLine(to: p)
                current = p
                lastCubicControl = nil; lastQuadControl = nil
            case "H":
                guard let x = nextNumber() else { return path }
                let p = CGPoint(x: relative ? current.x + x : x, y: current.y)
                path.addLine(to: p)
                current = p
                lastCubicControl = nil; lastQuadControl = nil
            case "V":
                guard let y = nextNumber() else { return path }
                let p = CGPoint(x: current.x, y: relative ? current.y + y : y)
                path.addLine(to: p)
                current = p
                lastCubicControl = nil; lastQuadControl = nil
            case "C":
                guard let c1 = nextPoint(relative: relative),
                      let c2 = nextPoint(relative: relative),
                      let p = nextPoint(relative: relative) else { return path }
                path.addCurve(to: p, control1: c1, control2: c2)
                current = p
                lastCubicControl = c2; lastQuadControl = nil
            case "S":
                guard let c2 = nextPoint(relative: relative),
                      let p = nextPoint(relative: relative) else { return path }
                let c1 = lastCubicControl.map { CGPoint(x: 2 * current.x - $0.x, y: 2 * current.y - $0.y) } ?? current
                path.addCurve(to: p, control1: c1, control2: c2)
                current = p
                lastCubicControl = c2; lastQuadControl = nil
            case "Q":
                guard let c1 = nextPoint(relative: relative),
                      let p = nextPoint(relative: relative) else { return path }
                path.addQuadCurve(to: p, control: c1)
                current = p
                lastQuadControl = c1; lastCubicControl = nil
            case "T":
                guard let p = nextPoint(relative: relative) else { return path }
                let c1 = lastQuadControl.map { CGPoint(x: 2 * current.x - $0.x, y: 2 * current.y - $0.y) } ?? current
                path.addQuadCurve(to: p, control: c1)
                current = p
                lastQuadControl = c1; lastCubicControl = nil
            case "Z":
                path.closeSubpath()
                current = subpathStart
                lastCubicControl = nil; lastQuadControl = nil
            default:
                return path
            }
        }
        return path
    }
}

/// The cursive "murmur" wordmark, rendered from SVG path data (viewBox 252x28).
struct MurmurLogoShape: Shape {
    static let viewBox = CGRect(x: 0, y: 0, width: 252, height: 28)
    static let cached: CGPath = SVGPath.cgPath(from: murmurLogoPathData)

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width / Self.viewBox.width, rect.height / Self.viewBox.height)
        let scaledSize = CGSize(width: Self.viewBox.width * scale, height: Self.viewBox.height * scale)
        var transform = CGAffineTransform.identity
            .translatedBy(x: rect.midX - scaledSize.width / 2, y: rect.midY - scaledSize.height / 2)
            .scaledBy(x: scale, y: scale)
        guard let transformed = Self.cached.copy(using: &transform) else { return Path() }
        return Path(transformed)
    }
}

